mapper.select:
SELECT r.id AS restaurantId, r.name AS restaurantName, o_summary.timeKey, o_summary.orderCount, IFNULL(oi_summary.totalItemsSold, 0) AS totalItemsSold, o_summary.totalSales FROM restaurant r INNER JOIN ( SELECT restaurant_id, CASE WHEN #{granularity} = 'day' THEN DATE(created_time) WHEN #{granularity} = 'week' THEN CONCAT(YEAR(created_time), '-W', WEEK(created_time,1)) WHEN #{granularity} = 'month' THEN DATE_FORMAT(created_time, '%Y-%m') END AS timeKey, COUNT(*) AS orderCount, SUM(total_amount) AS totalSales FROM orders WHERE status = 6
AND created_time >= #{startDate}
AND created_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND restaurant_id = #{restaurantId}
GROUP BY restaurant_id, timeKey ) o_summary ON r.id = o_summary.restaurant_id LEFT JOIN ( SELECT o.restaurant_id, CASE WHEN #{granularity} = 'day' THEN DATE(o.created_time) WHEN #{granularity} = 'week' THEN CONCAT(YEAR(o.created_time), '-W', WEEK(o.created_time,1)) WHEN #{granularity} = 'month' THEN DATE_FORMAT(o.created_time, '%Y-%m') END AS timeKey, SUM(oi.quantity) AS totalItemsSold FROM orders o JOIN order_items oi ON o.id = oi.order_id WHERE o.status = 6
AND o.created_time >= #{startDate}
AND o.created_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
AND o.restaurant_id = #{restaurantId}
GROUP BY o.restaurant_id, timeKey ) oi_summary ON r.id = oi_summary.restaurant_id AND o_summary.timeKey = oi_summary.timeKey ORDER BY o_summary.timeKey ASC

SELECT COUNT(o.id) AS orderCount, COALESCE(SUM(o.total_amount), 0) AS totalSales,
( SELECT COALESCE(SUM(oi.quantity), 0) FROM order_items oi JOIN orders o2 ON oi.order_id = o2.id WHERE o2.status = 6
AND o2.restaurant_id = #{restaurantId}
AND o2.created_time >= #{startDate}
AND o2.created_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)
) AS totalItemsSold
FROM orders o WHERE o.status = 6
AND o.restaurant_id = #{restaurantId}
AND o.created_time >= #{startDate}
AND o.created_time < DATE_ADD(#{endDate}, INTERVAL 1 DAY)

SELECT d.id AS dishId, d.name AS dishName, r.name AS restaurantName, SUM(oi.quantity) AS totalSold, SUM(oi.quantity * oi.dish_price) AS totalSales FROM orders o JOIN order_items oi ON o.id = oi.order_id JOIN dish d ON oi.dish_id = d.id JOIN restaurant r ON o.restaurant_id = r.id
o.status = 6
AND DATE(o.pay_time) >= #{startDate}
AND DATE(o.pay_time) <= #{endDate}
AND o.restaurant_id = #{restaurantId}
GROUP BY d.id, d.name, r.name ORDER BY totalSold DESC
